// spot-bl.js — Spotify Deep Dive ▸ Bottom Line ▸ General (BL-GEN, docs/PROFILE_PLAYBOOK.md §13).
//
// COPIED from js/overviews/tsm-bl.js (itself a copy of the AMZN closure aMarginsBody · aBridgeBody · aNetBridgeBody ·
// aSbcBody · expenseTabsBody · aBlFootGeneral), then adapted — never reimplemented:
//   • data: ./spot-bbg.js (Bloomberg export, generated by scripts/bbg_extract.py) for the income statement and
//     consensus; ./spot-bl-data.js for the reported functional expense lines (BBG snapshots, tied to the Form 20-F),
//     SBC by function and the expense-line dives; ../results-data/spot.js for the quarterly operating-income series.
//   • EUR throughout (Spotify reports in euros; the line is not an ADR). No WACC, no terminal growth anywhere.
//   • expense lines = Spotify's own (20-F Item 5): cost of revenue · research and development · sales and marketing ·
//     general and administrative. There is no "other operating" line, so the bridge has no such bar.
//   • no "Normalized" net income: Spotify's non-operating items are shown as one reconciling bar (see spotNetBridge).
//   • Summit series: read from js/results-data/spot.js, where the Summit DCF snapshots are FROZEN (rule 10 —
//     coded directly, not live): FY2026–FY2028 from the snapshot of Oct 22 2026 (after 3Q26). Forward years only.
//   • inline <style> blocks moved to css/overview.css (.ov-spot-dd scope).
import { SUMMIT_CAT, SUMMIT_INK } from '../viz-palette.js';
import { spotBBG } from './spot-bbg.js';
import { spotResults } from '../results-data/spot.js';
import { SPOT_OPEX_YEARS, SPOT_OPEX, SPOT_OPEXQ, SPOT_SBC, SPOT_EW_LINES, SPOT_EW_SRC } from './spot-bl-data.js';

// The Bloomberg export carries every forward quarter it has; the profile shows TWO quarters past the last print (analyst rule),
// so the trailing quarters are cut here once, from every quarterly array (qtrs, q, qF) of the export.
(function(){
  var cut = Math.max(0, spotBBG.qtrs.length - 1 - spotBBG.qtrs.indexOf('4Q26E') - 1);   // quarters after 1Q27E
  if (!cut) return;
  spotBBG.qtrs = spotBBG.qtrs.slice(0, spotBBG.qtrs.length - cut);
  (function walk(o){
    if (!o || typeof o !== 'object' || Array.isArray(o)) return;
    Object.keys(o).forEach(function(k){
      var v = o[k];
      if ((k === 'q' || k === 'qF') && Array.isArray(v)) o[k] = v.slice(0, v.length - cut);
      else walk(v);
    });
  })(spotBBG);
})();

var BRAND=SUMMIT_CAT[0], BRAND2=SUMMIT_CAT[1], SQUID=SUMMIT_INK, GREEN='#2E8B57', GRAY='#9AA4B0';
// spot-bbg.js keeps Bloomberg's field slugs where Spotify's labels differ from Amazon's (the extractor's CODE map is
// Amazon-shaped). Alias the ones this code reads, so the copied functions run unchanged.
(function(is){ var AL={ rev:'revenue', pretax:'preTaxIncome', rnd:'techInfra', cogs:'costOfRevenue', sbc:'stockBasedCompensation' };
  Object.keys(AL).forEach(function(k){ if(!is[k] && is[AL[k]]) is[k]=is[AL[k]]; }); })(spotBBG.is);
function esc(s){ if(s==null) return ''; return String(s).replace(/&/g,'&').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
// ═══ Deep Dive default tabs — built from the Results dataset (no re-hardcode) ═══════════════════
// Chart.js helpers (lazy: panes must be visible — offsetParent — before building).
var _aCharts={};
