var BR_FMT_D={ axis:function(v){return '€'+v.toFixed(Math.abs(v)<10?1:0)+'B';}, base:function(v){return '€'+v.toFixed(2)+'B';}, delta:function(v){return (v>=0?'+€':'−€')+Math.abs(v).toFixed(2)+'B';} };
var BR_FMT_BPS={ axis:function(v){return v.toFixed(0)+'%';}, base:function(v){return v.toFixed(1)+'%';}, delta:function(v){var b=Math.round(v*100); return (b>=0?'+':'−')+Math.abs(b)+' bps';} };
// Synthetic "opex row" for a forward year (fi = 0..2 → FY26E..FY28E) built from BBG consensus, shaped
// exactly like an SPOT_OPEX row so aBridgeBuildupSteps / aBuildBrPie work on it unchanged. otherOpex is the
// residual so revenue − Σcost = operating income reconciles to the reported consensus OI.
// adj = optional {cogs,rnd,gAdmin,marketing} percent tweaks vs consensus. The "other"
// residual is held at consensus, so with no adj OI reconciles to consensus; move a slider and OI floats.
var FX_LINES=[{k:'cogs',lab:'Cost of revenue'},{k:'rnd',lab:'R&amp;D'},{k:'sm',lab:'S&amp;M'},{k:'gAdmin',lab:'G&amp;A'}];
function aFwdOpexRow(fi, adj){
  function f(k){ var s=spotBBG.is[k]; return s?s.f[fi]:null; }
  var rev=f('rev'), oi=f('oi'); if(rev==null||oi==null) return null;
  // BBG gives forward gross profit, not always COGS → derive COGS = revenue − gross profit when missing.
  var cogs=f('cogs'); if(cogs==null){ var gp=f('grossProfit'); cogs=(gp!=null)?(rev-gp):0; } cogs=cogs||0;
  var rnd=f('rnd')||0, mkt=f('marketing')||0, ga=f('gAdmin')||0;   // BBG 'marketing' = sales & marketing
  var other=rev-cogs-rnd-mkt-ga-oi;   // consensus residual, held fixed
  adj=adj||{}; function A(v,k){ return v*(1+((adj[k]||0)/100)); }
  return { p:'FY'+String(spotBBG.yearsF[fi]).slice(2)+'E', revenue:rev, costOfSales:A(cogs,'cogs'), rnd:A(rnd,'rnd'),
    gAdmin:A(ga,'gAdmin'), sm:A(mkt,'sm'), otherOpex:other };
}
