  var oi=aIsVal('oi',y), tax=aIsVal('tax',y), pretax=aIsVal('pretax',y), net=aIsVal('netIncome',y), rev=aIsVal('rev',y);
  if(oi==null||net==null||tax==null||pretax==null) return;
  function B(x){ return x==null?0:x/1000; }
