  var plug = net - (pretax - tax);             // non-controlling interests (and consensus rounding)
  var run=B(oi), steps=[{label:'Op. income', kind:'base', color:'#1E2733', range:[0,run], runAfter:run, val:B(oi)}];
  function step(lab,d){ var lo=run; run=lo+d; steps.push({label:lab, kind:d>=0?'up':'down', color:'#6B7683', dc:'#6B7683', range:[Math.min(lo,run),Math.max(lo,run)], runAfter:run, val:d}); }
  step('Non-operating, net', B(O));
