// Expense-line full dives — opened from an Expenses card via data-detail="exp:<key>". VISUAL, not prose.
var EW_CSS='';   // the explorer's styles live in css/overview.css (.ov-spot-dd .ew-* / .exp-*) — no inline <style>
var EW_LABS=SPOT_OPEX_YEARS.map(function(y){ return '’'+String(y).slice(2); });
